package medium;public class CountOfSmallerNumbersAfterSelf{public static java.util.List<Integer>countSmaller(int[]n){java.util.List<Integer>r=new java.util.ArrayList<>();int[]a=n.clone();java.util.Arrays.sort(a);for(int i=0;i<n.length;i++){int idx=java.util.Arrays.binarySearch(a,n[i]);r.add(idx);if(idx<a.length-1)java.util.System.arraycopy(a,idx+1,a,idx,a.length-idx-1);a[a.length-1]=-2147483648;}return r;}public static void main(String[]args){System.out.println("Smaller: "+countSmaller(new int[]{5,2,6,1}));}}
